import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"HTAP","description":"","frontmatter":{"title":"HTAP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/htap.md","filePath":"cs/htap.md","lastUpdated":1789023840000}'),h={name:"cs/htap.md"};function P(T,a,A,_,E,m){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="htap" tabindex="-1">HTAP <a class="header-anchor" href="#htap" aria-label="Permalink to &quot;HTAP&quot;">​</a></h1><div class="epigraph"><p>同一份（或可对齐快照的）数据既要短事务又要扫描分析。引擎用双格式、双集群或可更新列存，隔离的是资源与新鲜度合同。</p><footer>—— 据 Özcan et al. HTAP 综述；C-Store/HyPer 谱系；OLTP-OLAP 边界</footer></div><p><a href="/cs/storage-compute-separation">上一课</a>让计算弹性。本课不挂盘。缺口是工作负载混合：OLTP 要点查与索引，OLAP 要列扫。传统做法 ETL 到数仓，新鲜度小时级。HTAP（Hybrid Transactional/Analytical Processing）要秒级或事务级新鲜。分布式序列接近收口，NewSQL 下一课归产品族。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一条缓冲池、一种页格式难同时最优。路径：① 行存主 + 异步列副本（CDC）；② 可更新列存 + delta；③ 内存行 + 列批次（HyPer 热切）；④ 存算分离上两计算引擎读同一 WAL。缺口是<strong>新鲜度、隔离、资源隔离</strong>：分析扫打爆 OLTP 缓冲，2Q 抗扫描不够还要 QoS、WLM。</p><p>快照：分析用只读快照不挡 OLTP 写，但 GC 水位或列副本延迟仍在。</p><p><span class="marginnote">HTAP 一词工业界常用。HyPer 热切、TiFlash 列副本质是工程点。本课合同不是商标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明 SLA：分析可落后 \\(x\\) 秒。路由：短查询走行，扫走列。物化视图在 HTAP 里当列侧预聚合。计划：同一 SQL 两套代价模型。</p><p>与 shuffle：列侧 MPP 仍要连接。事务写只打行侧，列侧追。</p>',10)),(e(),n(c,null,{default:r(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22OLTP%20%E5%86%99%22%5D%20--%3E%20ROW%5B%22%E8%A1%8C%E5%BC%95%E6%93%8E%22%5D%0A%20%20ROW%20--%3E%20CDC%5B%22%E5%A4%8D%E5%88%B6%20%2F%20delta%22%5D%0A%20%20CDC%20--%3E%20COL%5B%22%E5%88%97%E5%BC%95%E6%93%8E%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20ROUTE%5B%22%E6%8C%89%E5%BD%A2%E7%8A%B6%E8%B7%AF%E7%94%B1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一致性：最强是同一 MVCC 戳两引擎可读；常见是列落后。读己之写：刚写去列侧可能没有，要路由到行或等。TDE 两份。vacuum 与列 compaction 双重 GC。</p><p>校准：两套 I/O。计划回归：优化器突然把 OLTP 语句送到列扫。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列举 NewSQL 商标列表——下一课分类。也不把 HTAP 当向量数据库。湖仓后课是分析侧文件，新鲜度更松。</p><p>后课默认：混合负载要双路径或明确落后。NewSQL：SQL+分布式事务+分片的产品标签。</p><p>没有资源隔离的「一个库扛 HTAP」会把 2Q 与 latch 热点一起打穿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HTAP 用双格式或双引擎对齐新鲜度与资源。</li><li>分析快照与 OLTP 写的水位要合同。</li><li>NewSQL 下一课。</li><li>出处：HTAP 综述；HyPer/C-Store；CDC。</li></ul>',9))])}const f=l(h,[["render",P]]);export{C as __pageData,f as default};
